// Types fixture sources that Rolldown embeds as exact text.

declare module "*.bsmr" { const source: string; export default source; }
declare module "*.bzl" { const source: string; export default source; }
declare module "*.sh" { const source: string; export default source; }
declare module "*.go" { const source: string; export default source; }
declare module "*.py" { const source: string; export default source; }
declare module "*.mod" { const source: string; export default source; }
